  <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>

  <script>
    // ===== GLOBAL VARIABLES =====
    let canvas, ctx;
    let gui;
    let controls;
    let animationId = null;
    let isPaused = false;
    let network = null;

    // Color palette
    const colors = {
      background: '#05070f',
      backgroundGlow: '#101a3a',
      mainBranch: '#00e5ff',
      secondaryBranch: '#d6ff00',
      synapse: '#ff2bd6',
      pulse: '#fff36a',
      uiAccent: '#ffd400'
    };

    // ===== INITIALIZATION =====
    function init() {
      canvas = document.getElementById('main-canvas');
      ctx = canvas.getContext('2d');

      // Set up full canvas size
      canvas.width = 800;
      canvas.height = 800;

      // Initialize GUI
      initGUI();

      // Set initial background
      setBackgroundColor(colors.background);

      // Generate initial network
      regenerateNetwork();

      // Start animation loop
      animate();
    }

    // ===== GUI SETUP =====
    function initGUI() {
      gui = new dat.GUI({
        container: document.getElementById('gui-panel'),
        width: 280,
        height: 400
      });

      // Set colors for dat.gui
      gui._color = function(obj, prop, options = {}) {
        const result = gui.addColor(obj, prop);
        result.options = options;
        return result;
      };

      controls = {
        neuronCount: 4,
        growthSpeed: 1.5,
        maxDepth: 8,
        splitChance: 30,
        curvature: 0.15,
        maxLength: 150,
        synapseThreshold: 60,
        glowStrength: 2.5,
        pulseSpeed: 1.5,
        pulseFrequency: 0.8,
        pulseBrightness: 1.2,
        bgColor: '#05070f',
        branchColor: '#00e5ff',
        accentBranchColor: '#d6ff00',
        synapseColor: '#ff2bd6',
        pulseColor: '#fff36a',

        // Internal state
        isGrowing: true,
        isPaused: false
      };

      // Growth folder
      const growthFolder = gui.addFolder('Growth');
      growthFolder.add(controls, 'neuronCount', 1, 8, 1).name('Neuron Count');
      growthFolder.add(controls, 'growthSpeed', 0.5, 5, 0.1).name('Growth Speed');
      growthFolder.add(controls, 'maxDepth', 3, 12, 1).name('Max Branch Depth');
      growthFolder.add(controls, 'splitChance', 0, 100, 1).name('Split Chance');
      growthFolder.add(controls, 'curvature', 0, 1, 0.01).name('Branch Curvature');
      growthFolder.add(controls, 'maxLength', 50, 200, 1).name('Max Branch Length');
      growthFolder.open();

      // Synapses folder
      const synapsesFolder = gui.addFolder('Synapses');
      synapsesFolder.add(controls, 'synapseThreshold', 20, 150, 1).name('Distance Threshold');
      synapsesFolder.add(controls, 'glowStrength', 0, 5, 0.1).name('Glow Strength');
      synapsesFolder.open();

      // Pulses folder
      const pulsesFolder = gui.addFolder('Pulses');
      pulsesFolder.add(controls, 'pulseSpeed', 0.5, 5, 0.1).name('Pulse Speed');
      pulsesFolder.add(controls, 'pulseFrequency', 0.1, 3, 0.1).name('Pulse Frequency');
      pulsesFolder.add(controls, 'pulseBrightness', 0.2, 2, 0.1).name('Pulse Brightness');
      pulsesFolder.open();

      // Visuals folder
      const visualsFolder = gui.addFolder('Visuals');
      visualsFolder.addColor(controls, 'bgColor').name('Background Color')
        .onChange(val => {
          setBackgroundColor(val);
          controls.bgColor = val;
        });
      visualsFolder.addColor(controls, 'branchColor').name('Branch Color')
        .onChange(val => {
          controls.branchColor = val;
        });
      visualsFolder.addColor(controls, 'accentBranchColor').name('Accent Branch Color')
        .onChange(val => {
          controls.accentBranchColor = val;
        });
      visualsFolder.addColor(controls, 'synapseColor').name('Synapse Color')
        .onChange(val => {
          controls.synapseColor = val;
        });
      visualsFolder.addColor(controls, 'pulseColor').name('Pulse Color')
        .onChange(val => {
          controls.pulseColor = val;
        });
      visualsFolder.open();

      // Buttons
      document.getElementById('regenerate-btn').addEventListener('click', regenerateNetwork);
      document.getElementById('clear-btn').addEventListener('click', clearCanvas);
      document.getElementById('pause-btn').addEventListener('click', togglePause);
    }

    function setBackgroundColor(color) {
      document.body.style.backgroundColor = color;
      document.getElementById('main-canvas').style.backgroundColor = color;
    }

    // ===== NEURON & BRANCH SYSTEM =====
    function Neuron(x, y) {
      this.x = x;
      this.y = y;
      this.branches = [];
      this.id = Math.random().toString(36).substr(2, 9);

      // Grow the neuron recursively
      this.grow(depth = 0);
    }

    Neuron.prototype.grow = function(depth) {
      if (depth >= controls.maxDepth || !this.isGrowing) return;

      // Create a branch
      const branch = new Branch(this.x, this.y, this, depth);
      this.branches.push(branch);

      // Occasionally create side branches
      if (Math.random() < (controls.splitChance / 100) && depth < controls.maxDepth - 2) {
        const sideAngle = this.getRandomDirection();
        const sideLen = branch.length * (0.3 + Math.random() * 0.4);
        const sideX = branch.x + Math.cos(sideAngle) * sideLen;
        const sideY = branch.y + Math.sin(sideAngle) * sideLen;
        const sideNeuron = new Neuron(sideX, sideY);
        // Merge side neuron branches
        sideNeuron.branches = sideNeuron.branches.concat(this.branches.splice(-1));
      }

      // Continue growing from the tip
      if (this.isGrowing && branch.length < controls.maxLength) {
        setTimeout(() => {
          this.grow(depth + 1);
        }, Math.random() * 100 / controls.growthSpeed + 50 / controls.growthSpeed);
      }
    };

    Neuron.prototype.getRandomDirection = function() {
      return Math.random() * Math.PI * 2;
    };

    // ===== BRANCH CLASS =====
    function Branch(startX, startY, parentNeuron, depth) {
      this.startX = startX;
      this.startY = startY;
      this.parent = parentNeuron;
      this.depth = depth;
      this.points = [];
      this.id = Math.random().toString(36).substr(2, 9);

      // Generate the branch curve
      this.generate();

      // Store original thickness based on depth
      this.baseThickness = Math.max(1, 3 - depth * 0.2);
      this.thickness = this.baseThickness * (0.8 + Math.random() * 0.4);
    }

    Branch.prototype.generate = function() {
      let x = this.startX;
      let y = this.startY;
      const points = [];
      let remainingLength = controls.maxLength;

      while (remainingLength > 0 && this.points.length < 200) {
        // Calculate step distance
        const step = Math.min(remainingLength, 10 + Math.random() * 5);
        remainingLength -= step;

        // Get current direction and add curvature
        const angle = this.getAngle();
        const curvedAngle = angle + (Math.random() - 0.5) * controls.curvature;

        // Move forward
        x += Math.cos(curvedAngle) * step;
        y += Math.sin(curvedAngle) * step;

        // Add some random offset for organic feel
        x += (Math.random() - 0.5) * 3;
        y += (Math.random() - 0.5) * 3;

        points.push({ x, y });
      }

      this.points = points;
      this.length = points.reduce((sum, p, i) => sum + (i > 0 ? Math.hypot(p.x - points[i-1].x, p.y - points[i-1].y) : 0), 0);
    };

    Branch.prototype.getAngle = function() {
      if (this.points.length < 2) return Math.atan2(this.startY - canvas.height/2, this.startX - canvas.width/2);
      const last = this.points[this.points.length - 1];
      const prev = this.points[this.points.length - 2];
      return Math.atan2(last.y - prev.y, last.x - prev.x);
    };

    // ===== SYNAPSE DETECTION =====
    function detectSynapses() {
      const synapses = [];

      for (let i = 0; i < network.branches.length; i++) {
        for (let j = i + 1; j < network.branches.length; j++) {
          const branch1 = network.branches[i];
          const branch2 = network.branches[j];

          // Check if either branch has remaining points
          if (branch1.points.length === 0 || branch2.points.length === 0) continue;

          // Get the tip of each branch
          const tip1 = branch1.points[branch1.points.length - 1];
          const tip2 = branch2.points[branch2.points.length - 1];

          // Calculate distance between tips
          const dist = Math.hypot(tip2.x - tip1.x, tip2.y - tip1.y);

          if (dist < controls.synapseThreshold) {
            // Check for duplicate synapses
            const isDuplicate = network.synapses.some(s =>
              (s.branch1Id === branch1.id && s.branch2Id === branch2.id) ||
              (s.branch1Id === branch2.id && s.branch2Id === branch1.id)
            );

            if (!isDuplicate) {
              synapses.push({
                branch1Id: branch1.id,
                branch2Id: branch2.id,
                tip1: { x: tip1.x, y: tip1.y },
                tip2: { x: tip2.x, y: tip2.y },
                strength: 1 - (dist / controls.synapseThreshold),
                age: 0
              });
            }
          }
        }
      }

      network.synapses = synapses;
    }

    // ===== PULSE ANIMATION =====
    function Pulse(branch1, branch2) {
      this.branch1 = branch1;
      this.branch2 = branch2;
      this.progress = 0;
      this.totalProgress = 0;
      this.active = false;
      this.color = controls.pulseColor;
      this.speed = controls.pulseSpeed;
      this.frequency = controls.pulseFrequency;
      this.brightness = controls.pulseBrightness;

      // Calculate initial total progress
      this.calculateTotalProgress();
    }

    Pulse.prototype.calculateTotalProgress = function() {
      const start1 = this.branch1.points[0];
      const end1 = this.branch1.points[this.branch1.points.length - 1];
      const start2 = this.branch2.points[0];
      const end2 = this.branch2.points[this.branch2.points.length - 1];

      const d1 = Math.hypot(end1.x - start1.x, end1.y - start1.y);
      const d2 = Math.hypot(end2.x - start2.x, end2.y - start2.y);
      this.totalProgress = d1 + d2;
    };

    Pulse.prototype.update = function(deltaTime) {
      if (!this.active) {
        // Randomly start a new pulse
        if (Math.random() < this.frequency * deltaTime / 1000) {
          this.active = true;
          this.progress = 0;
        }
        return;
      }

      this.progress += this.speed * deltaTime / 1000;
      this.age += deltaTime / 1000;

      if (this.progress >= this.totalProgress) {
        this.active = false;
        this.progress = 0;
        this.age = 0;
      }
    };

    Pulse.prototype.draw = function() {
      if (!this.active) return;

      const progress = this.progress;
      const speedFactor = Math.sin(progress * Math.PI) * 0.5 + 0.5;
      const pulseAlpha = 0.3 + speedFactor * 0.7;
      const pulseWidth = 2 + speedFactor * 3;

      // Get positions along the branches based on progress
      const pos1 = this.getPointOnBranch(this.branch1, progress * 0.5);
      const pos2 = this.getPointOnBranch(this.branch2, progress * 0.5 + 0.5);

      if (!pos1 || !pos2) return;

      // Draw pulse line
      ctx.save();
      ctx.strokeStyle = this.color;
      ctx.globalAlpha = pulseAlpha * this.brightness;
      ctx.lineWidth = pulseWidth;
      ctx.lineCap = 'round';
      ctx.shadowColor = this.color;
      ctx.shadowBlur = 15 * this.brightness;

      // Interpolate between the two points for smooth movement
      const interpX = pos1.x + (pos2.x - pos1.x) * 0.3;
      const interpY = pos1.y + (pos2.y - pos1.y) * 0.3;

      ctx.beginPath();
      ctx.moveTo(pos1.x, pos1.y);
      ctx.lineTo(interpX, interpY);
      ctx.stroke();
      ctx.restore();
    };

    Pulse.prototype.getPointOnBranch = function(branch, progress) {
      if (branch.points.length === 0) return null;

      const index = Math.min(
        Math.floor(progress * (branch.points.length - 1)),
        branch.points.length - 1
      );
      const localProgress = (progress * (branch.points.length - 1)) % 1;

      const start = branch.points[index];
      const end = branch.points[Math.min(index + 1, branch.points.length - 1)];

      if (!end) return start;

      return {
        x: start.x + (end.x - start.x) * localProgress,
        y: start.y + (end.y - start.y) * localProgress
      };
    };

    // ===== RENDERING =====
    function render() {
      // Clear canvas with slight trailing effect for glow
      ctx.fillStyle = 'rgba(5, 7, 15, 0.1)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw vignette
      drawVignette();

      // Draw background glow
      drawBackgroundGlow();

      // Draw all branches
      network.branches.forEach(branch => {
        this.drawBranch(branch);
      });

      // Draw all synapses
      network.synapses.forEach(synapse => {
        this.drawSynapse(synapse);
      });

      // Draw all pulses
      network.pulses.forEach(pulse => {
        pulse.draw();
      });
    }

    function drawBranch(branch) {
      if (branch.points.length < 2) return;

      ctx.save();
      ctx.strokeStyle = controls.branchColor;
      ctx.globalAlpha = 0.8;
      ctx.lineWidth = branch.thickness;
      ctx.lineCap = 'round';
      ctx.shadowColor = controls.branchColor;
      ctx.shadowBlur = 10;

      ctx.beginPath();
      ctx.moveTo(branch.points[0].x, branch.points[0].y);

      for (let i = 1; i < branch.points.length; i++) {
        ctx.lineTo(branch.points[i].x, branch.points[i].y);
      }

      ctx.stroke();
      ctx.restore();
    }

    function drawSynapse(synapse) {
      const progress = synapse.age / 2; // Pulse over time
      const pulseFactor = Math.sin(progress * Math.PI * 2) * 0.5 + 0.5;
      const glowAlpha = 0.5 + pulseFactor * 0.5;

      ctx.save();
      ctx.fillStyle = controls.synapseColor;
      ctx.globalAlpha = glowAlpha;
      ctx.shadowColor = controls.synapseColor;
      ctx.shadowBlur = controls.glowStrength * 5;

      // Draw circle at connection point
      const tip1 = synapse.tip1;
      const tip2 = synapse.tip2;

      const centerX = (tip1.x + tip2.x) / 2;
      const centerY = (tip1.y + tip2.y) / 2;
      const radius = 3 + pulseFactor * 2;

      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Draw connecting line
      ctx.save();
      ctx.strokeStyle = controls.synapseColor;
      ctx.globalAlpha = glowAlpha * 0.5;
      ctx.lineWidth = 1;
      ctx.lineCap = 'round';
      ctx.shadowColor = controls.synapseColor;
      ctx.shadowBlur = controls.glowStrength * 2;

      ctx.beginPath();
      ctx.moveTo(tip1.x, tip1.y);
      ctx.lineTo(tip2.x, tip2.y);
      ctx.stroke();
      ctx.restore();
    }

    function drawVignette() {
      const gradient = ctx.createRadialGradient(
        canvas.width / 2, canvas.height / 2, 0,
        canvas.width / 2, canvas.height / 2, Math.max(canvas.width, canvas.height) / 2
      );

      gradient.addColorStop(0, 'rgba(5, 7, 15, 0.3)');
      gradient.addColorStop(0.5, 'rgba(5, 7, 15, 0.1)');
      gradient.addColorStop(1, 'rgba(5, 7, 15, 0)');

      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    function drawBackgroundGlow() {
      const gradient = ctx.createRadialGradient(
        canvas.width / 2, canvas.height / 2, 0,
        canvas.width / 2, canvas.height / 2, canvas.width
      );

      gradient.addColorStop(0, '#101a3a');
      gradient.addColorStop(0.5, 'rgba(16, 26, 58, 0.5)');
      gradient.addColorStop(1, 'rgba(16, 26, 58, 0)');

      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    // ===== NETWORK MANAGEMENT =====
    function createNetwork() {
      const neurons = [];
      const branches = [];
      const synapses = [];

      // Generate 3-6 random seed neurons near the center
      const neuronCount = Math.max(3, Math.min(6, controls.neuronCount));

      for (let i = 0; i < neuronCount; i++) {
        // Random position near center
        const angle = (Math.PI * 2 * i) / neuronCount;
        const radius = 100 + Math.random() * 150;
        const x = canvas.width / 2 + Math.cos(angle) * radius;
        const y = canvas.height / 2 + Math.sin(angle) * radius;

        const neuron = new Neuron(x, y);
        neurons.push(neuron);

        // Collect all branches
        neuron.branches.forEach(branch => {
          branch.parent = neuron;
          branches.push(branch);
        });
      }

      // Detect synapses
      detectSynapses();

      // Create pulses for existing synapses
      const pulses = [];
      network.synapses.forEach(synapse => {
        const pulse = new Pulse(
          network.branches.find(b => b.id === synapse.branch1Id),
          network.branches.find(b => b.id === synapse.branch2Id)
        );
        if (pulse) pulses.push(pulse);
      });

      return { neurons, branches, synapses, pulses };
    }

    function regenerateNetwork() {
      // Clear existing canvas
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Create new network
      network = createNetwork();
    }

